<?php
namespace App\Controllers\Customer;
use App\Controllers\BaseController; use App\Libraries\Cart as CartLibrary; use App\Models\ProductImageModel; use App\Models\ProductModel;
class Cart extends BaseController { private function cart(){return new CartLibrary();} public function index(){ $c=$this->cart();$items=$c->rows();$excluded=array_map('intval',array_column($items,'product_id'));$products=new ProductModel();$products->where('status','active');if($excluded)$products->whereNotIn('id',$excluded);$recommendations=$products->orderBy('id','DESC')->findAll(4);$gallery=new ProductImageModel();foreach($recommendations as &$product){$product['gallery']=$gallery->where('product_id',(int)$product['id'])->orderBy('sort_order','ASC')->findAll();}unset($product);return view('customer/cart/index',['title'=>'Your cart','items'=>$items,'total'=>$c->total(),'recommendations'=>$recommendations,'cartQuantities'=>$c->quantities()]); } public function add(){ $p=(new ProductModel())->where('status','active')->find((int)$this->request->getPost('product_id')); if(!$p)return $this->response->setStatusCode(404)->setJSON(['message'=>'Product unavailable','csrfHash'=>csrf_hash()]); $cart=$this->cart();$qty=max(1,(int)$this->request->getPost('quantity'));$current=$cart->quantities()[(int)$p['id']]??0;$productQuantity=$cart->change((int)$p['id'],$qty,(int)$p['stock']); return $this->response->setJSON(['ok'=>true,'count'=>$cart->count(),'productQuantity'=>$productQuantity,'message'=>$productQuantity===$current?'Maximum stock reached':$p['name'].' added to cart','csrfHash'=>csrf_hash()]); }
 public function change(){ $productId=(int)$this->request->getPost('product_id');$delta=(int)$this->request->getPost('delta');if(!in_array($delta,[-1,1],true))return $this->response->setStatusCode(422)->setJSON(['message'=>'Invalid quantity change','csrfHash'=>csrf_hash()]);$p=(new ProductModel())->where('status','active')->find($productId);if(!$p)return $this->response->setStatusCode(404)->setJSON(['message'=>'Product unavailable','csrfHash'=>csrf_hash()]);$cart=$this->cart();$quantity=$cart->change($productId,$delta,(int)$p['stock']);return $this->response->setJSON(['ok'=>true,'count'=>$cart->count(),'productQuantity'=>$quantity,'message'=>$delta>0?$p['name'].' added to cart':'Cart updated','csrfHash'=>csrf_hash()]); }
 public function update(){ $this->cart()->update((int)$this->request->getPost('id'),(int)$this->request->getPost('quantity')); return redirect()->to('/cart'); } public function remove(){ $this->cart()->remove((int)$this->request->getPost('id')); return redirect()->to('/cart'); } }
